{
}

Method.Source:
    /// <summary>
    /// Find logo to use on customer-facing reports for specified customer.
    /// MPJ_13531_CustReportLogos
    /// </summary>
    /// <param name = "_custAccount">Customer account</param>
    /// <returns>Bitmap to use, or null if no specific image specified. (ie use default)</returns>
    static Image metGetCustReportLogo(CustAccount _custAccount, boolean _returnDefaultAsFallback = true)
    {
        Image           img;                
        METCustTable    metCustTable = METCustTable::find(_custAccount);
        if(metCustTable)
        {
            if(metCustTable.IndustryKey)
            {
                switch(METIndustryKeyTable::find(metCustTable.IndustryKey).Logo)
                {
                    case METIndustryKeyLogo::Logo1:
                        img = new Image();
                        img.setData(CompanyImage::findByRecord(CompanyInfo::find()).Image);
                        return img;

                    case METIndustryKeyLogo::Logo2:

                        CompanyInfo companyInfo = CompanyInfo::find();
                        METCompanyImage companyImage = METCompanyImage::find(
                            companyInfo.DataAreaId, 
                            companyInfo.TableId, 
                            companyInfo.RecId, 
                            false, 
                            METCompanyImageType::CompanyLogo);

                        if(companyImage && conLen(companyImage.Image) > 0)
                        {
                            img = new Image();
                            img.setData(companyImage.Image);
                            return img;
                        }
                        break;
                }                
            }
        }
        if(_returnDefaultAsFallback)
        {
            img = new Image();
            img.setData(CompanyImage::findByRecord(CompanyInfo::find()).Image);
            return img;
        }       
        return null;
    }

    /// <summary>
    /// MPJ_4050_CustomerPaymentsOpen
    /// </summary>
    /// <returns>
    /// wreturn MainContactWorker worker 
    /// </returns>
    [SysClientCacheDataMethod]
    public display Name getMETMainContactWorker()
    {
        HcmWorker       metHcmWorker;
        DirPersonName   metDirPersonName;
        DirPartyTable   metDirPartyTable;

        select RecId from metHcmWorker
                where metHcmWorker.RecId == this.MainContactWorker
            join RecId from metDirPersonName
                where metDirPersonName.Person == metHcmWorker.Person
            join RecId from metDirPartyTable
                where metDirPartyTable.RecId == metDirPersonName.Person;
 
        return metDirPartyTable.Name;

    }

    /// <summary>
    /// Validate field value.
    /// </summary>
    /// <param name = "p1">
    /// Field Id
    /// </param>
    /// <returns>true if validation succeeds; else false.</returns>
    boolean validateField(FieldId p1)
    {
        boolean ret;

        ret = next validateField(p1);

        switch (p1)
        {
            case fieldNum(CustTable, CredManAccountStatusId) :
                ret = this.metAllowAccountStatusUpdate();

        }

        return ret;
    }

    /// <summary>
    /// Account status cannot be updated to Closed if balance exists.
    /// </summary>
    /// <returns>true if ZERO balance; else false.</returns>
    public boolean metAllowAccountStatusUpdate()
    {
        boolean ret = true;

        if (this.CredManAccountStatusId == METConstants::custAccountStatusClosed
            && this.balanceAllCurrency() != 0)
        {
            ret = checkFailed("@MET:AccountClosingCheck");
        }

        if (ret && this.CredManAccountStatusId == METConstants::custAccountStatusClosed)
        {
            METCustTable    amexAccount;

            select  firstonly AccountNum from amexAccount
                    where amexAccount.AMEXChargeAccount == this.AccountNum;
            if (amexAccount)
            {
                ret = checkFailed(strfmt("@MET:CheckAccountforAMEX", amexAccount.AccountNum));
            }
        }



        return ret;
    }

    /// <summary>
    /// MPJ_3735_Aged Balance
    /// </summary>
    /// <param name = "_CustTable">
    /// get CustTable record
    /// </param>
    /// <returns>
    /// return ChainId Description
    /// </returns>
    [SysClientCacheDataMethod]
    public display Description getMETCompanyChainName()
    {
        smmBusRelChainGroup     metsmmBusRelChainGroup;

        select firstonly Description 
            from metsmmBusRelChainGroup
            where metsmmBusRelChainGroup.ChainId == this.CompanyChainId;
        
        return metsmmBusRelChainGroup.Description;

    }

    /// <summary>
    /// MPJ_3735_Aged Balance 
    /// </summary>
    /// <returns>
    /// return customer group name 
    /// </returns>
    [SysClientCacheDataMethod]
    public display Description getMETCustomerGroupName()
    {
        CustGroup   metCustGroup;

        select firstonly Name 
            from metCustGroup
            where metCustGroup.CustGroup == this.CustGroup;

        return metCustGroup.Name;
    }

    /// <summary>
    /// MPJ_1663_Amex balance to be added to Aged Balance Inquiry
    /// </summary>
    /// <returns>
    /// return AMEXBalance
    /// </returns>
    [SysClientCacheDataMethod]
    public  display METAMEXBalance getMETamexbalance()
    {
        METCustTable    metCustTable;

        select firstonly AMEXBalance 
            from metCustTable
            where  metCustTable.AccountNum  == this.AccountNum;

        return metCustTable.AMEXBalance;
    }

    /// <summary>
    /// Display Remaing amount
    /// </summary>
    /// <returns>Remaining Amount</returns>
    [SysClientCacheDataMethod]
    public display AmountMST getRemainAmountMST()
    {
        CustTrans custTrans;
        AmountMST remainAmountMST;

        select sum(AmountMST), sum(ExchAdjustment), sum(SettleAmountMST) 
            from custTrans
            where CustTrans.accountNum == this.accountNum
            &&    CustTrans.TransType  == LedgerTransType::Payment;
        
        remainAmountMST = custTrans.AmountMST + custTrans.ExchAdjustment - custTrans.SettleAmountMST;
        
        return remainAmountMST;
    }

