    /// <summary>
    /// Get last Activity record
    /// MPJ_22159 Collections note DCP 12/04/2022
    /// </summary>
    /// <returns>Activity record</returns>
    public smmActivities METGetActivityFields()
    {
        smmActivities               METActivity;
        smmActivityParentLinkTable  METActivityParent;
        smmActivityNumber           METActivityNumber;

        select firstOnly activityNumber, Purpose, TypeId, UserMemo, CreatedBy, CreatedDateTime
            from    METActivity
            order by CreatedDateTime desc

            exists join METActivityParent
            where   METActivityParent.ActivityNumber    == METActivity.ActivityNumber
            &&     (METActivityParent.ParentType        == smmActivityParentType::Customer
                 || METActivityParent.ParentType        == smmActivityParentType::Collections)
            &&      METActivityParent.RefRecId          == this.RecId
            &&      METActivityParent.RefTableId        == tableNum(CustTable);

        return METActivity;
    }

    /// <summary>
    /// Get community chest emails
    /// MPJ-15936 Customer Group Name DCP 20/06/2022
    /// </summary>
    /// <returns>Email</returns>
    [SysClientCacheDataMethod]
    public display Email emails()
    {
        str addresses;
        
        LogisticsIProvider logisticsProvider = LogisticsProviderFactory::getLogisticsProvider();

        if (logisticsProvider)
        {
            addresses = con2Str(logisticsProvider.electronicAddressLocatorsByRole(this.Party, METConstants::CommunityChestRole), METConstants::AddressSeperator);
        }

        return addresses;
    }
